{
  "name": "@wavelike/opencode-plugin",
  "version": "0.2.0",
  "license": "MIT",
  "description": "OpenCode plugin: sign in with your company account through Wavelike and use your organization's models.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "wavelike",
    "sso"
  ],
  "files": [
    "dist"
  ],
  "repository": {
    "type": "git",
    "url": "https://github.com/velos/wavelike.git",
    "directory": "packages/opencode-wavelike-auth"
  },
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./package.json": "./package.json"
  },
  "dependencies": {
    "@ai-sdk/openai-compatible": "^2.0.0",
    "@openauthjs/openauth": "^0.4.3"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.2.6",
    "effect": "^4.0.0"
  }
}
